Reject(()=>EffectPatch.Apply(baseline,"Particles",true,null,J("""{"Particles":{"SubLayer":{"Count":2001}}}"""),1920,1080),"MCP secondary range validated");
Reject(()=>EffectPatch.Apply(baseline,"Particles",true,null,J("""{"Particles":{"SubLayer":{"SubLayer":{}}}}"""),1920,1080),"MCP recursive layers rejected");
foreach(int style in Enumerable.Range(ParticleArtwork.FirstStyle,ParticleArtwork.Count))Check(new ParticleOptions {Style=style}.Validate().Style==style,"External style ID accepted: "+style);
var emblem=EffectPatch.Apply(baseline,"Particles",true,null,J("""{"Particles":{"Style":14,"RandomAppearance":true,"RandomStyles":[8,14],"SubLayer":{"Style":14,"RandomAppearance":true,"RandomStyles":[14]}}}"""),1920,1080);
var sharedEmblem=ShareCode.Decode(ShareCode.Encode(ShareProjection.Create(emblem,new(),new() {Effects=EffectKind.Particles})));
var restoredEmblem=VideoEffects.FromJson(sharedEmblem.Effects.ToJson());
Check(restoredEmblem.Particles.Style==14&&restoredEmblem.Particles.RandomStyles.SequenceEqual(new[]{8,14})&&restoredEmblem.Particles.SubLayer.Style==14&&restoredEmblem.Particles.SubLayer.RandomStyles.SequenceEqual(new[]{14}),"External style selection survives MCP patch, image-free share and profile roundtrip on both layers");
var bytes=new byte[ParticlePixels.Bytes];bytes[0]=230;bytes[3]=255;var custom=ParticlePixels.Encode(bytes);
var privateEffects=patched with {Particles=patched.Particles with {Image=custom,ImageName="private-main",RandomStyles=[7,8],SubLayer=patched.Particles.SubLayer with {Image=custom,ImageName="private-sub",RandomStyles=[7]}}};
var shared=ShareCode.Decode(ShareCode.Encode(ShareProjection.Create(privateEffects,new(),new() {Effects=EffectKind.Particles})));
Check(shared.Effects.Particles.Image.Length==0&&shared.Effects.Particles.SubLayer.Image.Length==0,"Share without images strips both uploads");
Check(shared.Effects.Particles.ImageName.Length==0&&shared.Effects.Particles.SubLayer.ImageName.Length==0,"Share without text strips both names");
Check(shared.Effects.Particles.RandomStyles.SequenceEqual(new[]{8})&&shared.Effects.Particles.SubLayer.RandomStyles.SequenceEqual(new[]{0}),"Image-free share keeps external style IDs and safely replaces sole custom selection");
var full=ShareCode.Decode(ShareCode.Encode(ShareProjection.Create(privateEffects,new(),new() {Effects=EffectKind.Particles,Images=true,Text=true})));
Check(full.Effects.Particles.SubLayer.Image==custom&&full.Effects.Particles.SubLayer.ImageName=="private-sub","Opt-in sharing preserves secondary upload");
var asset=AssetEffects.FromScreen(patched);Check(asset.Resolve(new()).Particles.SubLayer.Count==23,"Material overrides carry both layers");
Check(ParticleArtwork.All.Count==8,"A fresh base exposes only standard particle appearances");
string wire=patched.ToWire();var fullTokens=wire.Split(' ',StringSplitOptions.RemoveEmptyEntries);var tokens=ParameterFields(wire);
Check(tokens[0]=="37"&&fullTokens[tokens.Length]=="22"&&tokens[^60]=="1"&&tokens[^30]=="1","The render wire includes two bounded independent particle layers before the visual sequence");
Check(tokens[^58]=="80"&&tokens[^28]=="23","Wire counts add rather than multiply");
Check(tokens[^31]=="0"&&tokens[^1]=="1","Wire carries independent random rotation flags");
