// Deterministic off-screen render fixtures; no wallpaper binding or audio.
void Fixture(string name,ParticleOptions p)=>File.WriteAllText(Path.Combine(output,name+".wire"),new VideoEffects {Particles=p}.ToWire());
var sprite=new ParticleOptions {Enabled=true,Count=1,Size=240,Speed=0,Sway=0,Rotation=0,Twinkle=0,Fade=false,SizeRandom=0,SpeedRandom=0,Emitter=1,CenterX=.5,CenterY=.5,Opacity=1};
Fixture("none",sprite with {Enabled=false});
foreach(int style in new[]{0,1,2,3,4,6})Fixture("style-"+style,sprite with {Style=style});
Fixture("star-random",sprite with {RandomAppearance=true,RandomStyles=[6]});
Fixture("star-random-pair",sprite with {RandomAppearance=true,RandomStyles=[1,6]});
Fixture("star-sub",sprite with {Opacity=0,SubLayer=sprite with {Style=6}});
Fixture("star-sub-random",sprite with {Opacity=0,SubLayer=sprite with {RandomAppearance=true,RandomStyles=[6]}});
Fixture("tint-off",sprite with {Style=1,Color="#FF0000"});
Fixture("tint-on",sprite with {Style=1,Color="#FF0000",ColorEnabled=true});
Fixture("random-single",sprite with {RandomAppearance=true,RandomStyles=[1]});
Fixture("random-pair",sprite with {RandomAppearance=true,RandomStyles=[1,4]});
Fixture("sub-only",sprite with {Opacity=0,SubLayer=new() {Enabled=true,Style=4,Count=1,Size=240,Speed=0,Sway=0,Rotation=0,Twinkle=0,Fade=false,SizeRandom=0,Emitter=1,CenterX=.5,CenterY=.5,Opacity=1}});
Fixture("sub-tint-off",sprite with {Opacity=0,SubLayer=sprite with {Style=4,Color="#FF0000",SpeedRandom=.2}});
Fixture("sub-tint-on",sprite with {Opacity=0,SubLayer=sprite with {Style=4,Color="#FF0000",ColorEnabled=true,SpeedRandom=.2}});
Fixture("two-layers",sprite with {Style=1,CenterX=.25,SubLayer=new() {Enabled=true,Style=4,Count=1,Size=240,Speed=0,Sway=0,Rotation=0,Twinkle=0,Fade=false,SizeRandom=0,Emitter=1,CenterX=.75,CenterY=.5,Opacity=1}});
var rotating=sprite with {Style=6,Count=160,Size=55,Emitter=0,Emission=1,Rotation=90,Quality=2};
Fixture("rotation-random",rotating);
Fixture("rotation-uniform",rotating with {RandomRotation=false});
